"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";
import { Check, ChevronDown, ChevronUp, Search } from "@/components/ui/icons";

// Combobox: generated by UIX from the design system. Same variants and sizes as the Figma component.

const comboboxVariants = cva(
  "flex w-full items-center transition-colors h-10 px-3 gap-2 border border-line-default bg-surface hover:border-line-strong focus-within:ring-3 focus-within:ring-line-focus focus-within:border-line-focus has-[:disabled]:cursor-not-allowed has-[:disabled]:bg-disabled [&_svg]:size-4 [&_svg]:shrink-0 [&_svg]:text-icon-secondary rounded-md",
);

export interface ComboboxOption {
  value: string;
  label: string;
}

export interface ComboboxProps
  extends Omit<React.InputHTMLAttributes<HTMLInputElement>, "size" | "value" | "defaultValue" | "onChange" | "prefix" | "placeholder">,
    VariantProps<typeof comboboxVariants> {
  label?: React.ReactNode;
  /** Right-aligned note next to the label, for example "Optional". */
  secondaryLabel?: React.ReactNode;
  /** Message under the field. */
  feedback?: React.ReactNode;
  /** Same as feedback. */
  helper?: React.ReactNode;
  /** Error message; also marks the field invalid and replaces the feedback. */
  error?: string;
  /** The choices. */
  options: ComboboxOption[];
  /** Selected value (controlled). */
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  placeholder?: string;
  /** Shown when the search matches nothing. */
  emptyText?: string;
}

const Combobox = React.forwardRef<HTMLInputElement, ComboboxProps>(
  ({ className, label, secondaryLabel, feedback, helper, error, required, id, disabled, options, value, defaultValue, onValueChange, placeholder, emptyText = "No results found.", name, ...props }, ref) => {
    const autoId = React.useId();
    const fieldId = id ?? autoId;
    const listId = fieldId + "-list";
    const hintId = fieldId + "-hint";
    const message = error || feedback || helper;
    const [selected, setSelected] = React.useState(defaultValue ?? "");
    const current = value ?? selected;
    const chosen = options.find((item) => item.value === current);
    const [query, setQuery] = React.useState("");
    const [open, setOpen] = React.useState(false);
    const [active, setActive] = React.useState(0);
    const shown = options.filter((item) => item.label.toLowerCase().includes(query.toLowerCase()));
    const pick = (item: ComboboxOption) => {
      setSelected(item.value);
      onValueChange?.(item.value);
      setQuery("");
      setOpen(false);
    };
    return (
      <div data-slot="combobox" data-kind="field" className={cn("skin-quiet relative flex w-full flex-col gap-1-5", className)} onBlur={(event) => {
        if (!event.currentTarget.contains(event.relatedTarget)) setOpen(false);
      }}>
        {label ? <label htmlFor={fieldId} className={cn("text-label-medium text-fg-primary", disabled && "text-fg-disabled")}>{label}{required ? <span aria-hidden className="ml-0.5 text-fg-danger">*</span> : null}</label> : null}
        <div data-kind="field" className={cn(comboboxVariants({  }), error && "border-line-danger hover:border-line-danger focus-within:border-line-danger focus-within:ring-line-danger")}>
          <Search aria-hidden />
          <input
            ref={ref}
            id={fieldId}
            role="combobox"
            aria-expanded={open}
            aria-controls={listId}
            aria-autocomplete="list"
            aria-invalid={!!error}
            aria-describedby={message ? hintId : void 0}
            aria-activedescendant={open && shown[active] ? listId + "-" + active : void 0}
            autoComplete="off"
            disabled={disabled}
            required={required}
            placeholder={chosen ? chosen.label : placeholder}
            {...props}
            value={open ? query : chosen ? chosen.label : ""}
            onFocus={() => setOpen(true)}
            onChange={(event) => {
              setQuery(event.target.value);
              setActive(0);
              setOpen(true);
            }}
            onKeyDown={(event) => {
              if (event.key === "ArrowDown") {
                event.preventDefault();
                setOpen(true);
                setActive((active + 1) % Math.max(shown.length, 1));
              } else if (event.key === "ArrowUp") {
                event.preventDefault();
                setOpen(true);
                setActive((active + Math.max(shown.length, 1) - 1) % Math.max(shown.length, 1));
              } else if (event.key === "Enter" && open && shown[active]) {
                event.preventDefault();
                pick(shown[active]);
              } else if (event.key === "Escape") setOpen(false);
            }}
            className="min-w-0 flex-1 bg-transparent outline-none text-body-medium text-fg-primary placeholder:text-fg-tertiary disabled:text-fg-disabled disabled:cursor-not-allowed"
          />
          <button type="button" tabIndex={-1} disabled={disabled} aria-label={open ? "Close options" : "Open options"} onClick={() => setOpen(!open)} className="inline-flex shrink-0 cursor-pointer rounded-xs focus-visible:outline-none focus-visible:ring-3 focus-visible:ring-line-focus">
            {open ? <ChevronUp aria-hidden /> : <ChevronDown aria-hidden />}
          </button>
        </div>
        {name ? <input type="hidden" name={name} value={current} /> : null}
        {open ? (
          <ul role="listbox" id={listId} data-kind="overlay" className="absolute left-0 right-0 top-full z-50 mt-1 max-h-64 overflow-y-auto rounded-md p-1 bg-surface border border-line-default shadow-lg">
            {shown.length ? (
              shown.map((item, index) => (
                <li
                  key={item.value}
                  id={listId + "-" + index}
                  role="option"
                  aria-selected={item.value === current}
                  data-active={index === active ? "" : void 0}
                  onMouseDown={(event) => event.preventDefault()}
                  onClick={() => pick(item)}
                  onMouseEnter={() => setActive(index)}
                  className="flex cursor-pointer items-center h-[36px] px-2 gap-2 rounded-sm text-body-medium text-fg-primary aria-selected:text-fg-brand data-[active]:bg-subtle"
                >
                  <span className="min-w-0 flex-1">{item.label}</span>
                  {item.value === current ? <Check aria-hidden className="size-4 text-icon-brand" /> : null}
                </li>
              ))
            ) : (
              <li className="px-2 py-2 text-body-small text-fg-tertiary">{emptyText}</li>
            )}
          </ul>
        ) : null}
        {message ? <p id={hintId} className={cn("text-body-small text-fg-secondary", error && "text-fg-danger")}>{message}</p> : null}
      </div>
    );
  },
);
Combobox.displayName = "Combobox";

export { Combobox, comboboxVariants };
